// Shape tracks share the text track's settings (color, size, position, effect, animation,
// rotation, flips, backdrop); the shape replaces the text and Filled/Outline replaces weight.
const SHAPES=[['rect','Rectangle'],['rounded','Rounded box'],['pill','Pill'],['circle','Circle'],['ellipse','Oval'],['triangle','Triangle'],['diamond','Diamond'],['hexagon','Hexagon'],['star','Star'],['burst','Burst badge'],['heart','Heart'],['arrow','Arrow'],['bubble','Speech bubble'],['custom','Freeform (draw it)']];
