// Freeform shape editing: stretch, edit points, draw your own.
// Points are [u,v,k] in the shape's box (-.5….5 on each axis); k=1 is a smooth point, 0 a corner.
let shapeEdit=null,shapeDraw=null,shapeTap=null;
