function shapeFrame(t){let w=canvas.width,h=canvas.height,s=shapeSize(t,w);return {cx:w*t.x/100,cy:h*t.y/100,W:s.w,H:s.h,fx:t.flipH?-1:1,fy:t.flipV?-1:1,rot:(t.rotation||0)*Math.PI/180}}
