// "+ Video track" opens a pop-up to bring in a video: onto the main timeline, or on top as a layer.
function openVideoDialog(){if(exporting)return;pause();renderAssets();$('videoAsLayer').checked=false;$('videoDialog').showModal()}
function closeVideoDialog(){if($('videoDialog').open)$('videoDialog').close()}
function showStrip(id){requestAnimationFrame(()=>{let el=document.querySelector(`.duration-strip[data-id="${id}"]`);document.querySelector('.timeline')?.scrollIntoView({behavior:'smooth',block:'start'});el?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})})}
async function addVideoLayer(file){addTrack('video');let t=extraTracks.at(-1);targetTrack=t.id;if(typeof expandedStrip!=='undefined')expandedStrip=t.id;await loadTrackMedia(file);renderTracks();showStrip(t.id)}
async function videoDialogImport(files){files=[...(files||[])].filter(f=>f.type.startsWith('video/')||/\.(mp4|mov|webm|m4v|mkv)$/i.test(f.name));if(!files.length||exporting)return;let layer=$('videoAsLayer').checked;closeVideoDialog();if(layer){for(let f of files)await addVideoLayer(f);return}let count=clips.length;await importFiles(files);if(clips.length>count)showStrip(clips.at(-1).id)}
async function addFromDialog(i){let a=assets[i];if(!a||exporting)return;let layer=$('videoAsLayer').checked;closeVideoDialog();if(layer){await addVideoLayer(a.file);return}addAsset(i);showStrip(clips.at(-1).id)}
$('dropzone').addEventListener('drop',e=>{e.preventDefault();e.stopImmediatePropagation();$('dropzone').style.borderColor='';videoDialogImport(e.dataTransfer.files)},{capture:true});
// On phones the clip settings only appear while a clip is selected.
const inspectorWithPanel=inspector;inspector=function(){inspectorWithPanel();document.querySelector('.panel.right')?.classList.toggle('no-clip',!clips[selected])};
inspector();

// Tapping the dimmed area outside a pop-up closes it, like the × and Esc.
document.querySelectorAll('dialog.closable').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}));


// Media Vault (only inside TapShop): send the exported video or the project file to the
// dashboard, which stores it privately for this creator.
function inTapShop(){return window.parent!==window}
function sendToVault(items){window.parent.postMessage({type:'tapshop:vault-save',version:1,items},location.origin)}
let lastVideoExport=null;
const downloadWithVault=download;download=function(blob,name){if(blob?.type?.startsWith('video/')){lastVideoExport={blob,name};if(inTapShop())$('vaultVideo')?.classList.remove('hidden')}return downloadWithVault(blob,name)};
function saveVideoToVault(){if(!inTapShop()||!lastVideoExport)return;sendToVault([{...lastVideoExport,source:'video'}]);$('vaultVideo').classList.add('hidden');$('exportDialog').close()}
function saveProjectToVault(){if(!inTapShop()||exporting)return;let captured=null,real=download;download=(blob,name)=>{captured={blob,name}};try{saveProject()}finally{download=real}if(captured)sendToVault([{...captured,source:'video'}])}
if(!inTapShop())$('vaultProject')?.remove();

// Importing from the Vault: videos go on the main timeline (or on top as a layer), audio
// gets its own track, and a saved .tapshop.json project is reopened.
function openVaultPicker(kinds,asLayer){VaultPicker.open({title:'From your Media Vault',kinds,accept:i=>i.kind!=='project'||/\.tapshop\.json$/i.test(i.name),onPick:it=>importVaultItem(it,asLayer),drag:vaultDrag})}
async function importVaultItem(item,asLayer,at){if(exporting)return;let file;try{toast('Loading '+item.name+'…');file=await VaultPicker.file(item)}catch(e){toast(e.message);return}
 if(item.kind==='video'){if(asLayer){if(at==null){await addVideoLayer(file);return}addTrack('video');let t=extraTracks.at(-1);t.offset=at;targetTrack=t.id;if(typeof expandedStrip!=='undefined')expandedStrip=t.id;await loadTrackMedia(file);renderTracks();render();showStrip(t.id);return}let n=clips.length;await importFiles([file]);if(clips.length>n){if(at!=null){clips.at(-1).offset=at;render()}showStrip(clips.at(-1).id)}return}
 if(item.kind==='audio'){addTrack('audio');let t=extraTracks.at(-1);if(at!=null)t.offset=at;targetTrack=t.id;if(typeof expandedStrip!=='undefined')expandedStrip=t.id;await loadTrackMedia(file);renderTracks();if(at!=null)render();showStrip(t.id);return}
 if(item.kind==='project'||/\.tapshop\.json$/i.test(item.name)){await restoreProject(file);return}
 toast(item.kind==='image'?'Images go in the Design Studio. Open it from “← Studio”.':'That file can’t go on the video timeline.')}
// Dragging a file from the Vault picker onto the timeline: it lands where it's dropped.
// Videos dropped on the layer rows go on top; anywhere else on the timeline they join the
// main video. Audio always gets its own track, and a project reopens.
let vaultDropLine=null;
